export function QqIcon({
  name,
  size = 16,
  className,
  style,
  title,
}: {
  name: QqIconName;
  /** 边长（px）；QQ 这套图标原生是 16 网格。 */
  size?: number;
  className?: string;
  style?: CSSProperties;
  /** 传了才当图片曝光给读屏；否则纯装饰。 */
  title?: string;
}) {
  const icon = QQ_ICONS[name];
  return (
    <svg
      className={className}
      style={style}
      width={size}
      height={size}
      viewBox={icon.viewBox}
      fill="none"
      role={title ? 'img' : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
      focusable="false"
    >
      {title ? <title>{title}</title> : null}
      {icon.body}
    </svg>
  );
}
